    },
    "factor_updates": [
      {
        "factor": "February 2026 death toll pace",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 dead/missing by late February; continuing pace into March–April increases the chance of hitting 900 by end-April."
      },
      {
        "factor": "High early-year mortality trend",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Record pace signals sustained elevated risk, supporting a non-negligible probability of reaching 900 if conditions persist."
      },
      {
        "factor": "Annual base-rate context",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Long-run annual toll near 2,000–2,185 suggests that a very deadly early year could push cumulative counts toward the 900 mark by April."
      },
      {
        "factor": "Data verification and potential revisions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Counts are still being verified; revisions could tilt totals upward or downward."
      },
      {
        "factor": "Weather/SAR conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Worsening sea states or strained SAR capacity could elevate fatalities, moving the count toward 900 more quickly."
      }
    ],
    "synthesis_rationale": "Begin with a cautious base-rate anchor, then apply orderly upward updates from the pace and trend factors, tempered by verification uncertainty and SAR variability; the calibration yields a posterior around 0.64 with a broad enough range to reflect volatility."
  }
}

